import java.util.*;

class Solution {
  public long countGoodIntegers(int n, int k) {
    Set<String> signatures = new HashSet<>();
    int half = (n + 1) / 2;
    int start = (int) Math.pow(10, half - 1), end = (int) Math.pow(10, half);
    for (int prefix = start; prefix < end; prefix++) {
      String left = Integer.toString(prefix),
          palindrome = left + new StringBuilder(left.substring(0, n / 2)).reverse();
      if (Long.parseLong(palindrome) % k != 0) continue;
      char[] digits = palindrome.toCharArray();
      Arrays.sort(digits);
      signatures.add(new String(digits));
    }
    long[] factorial = new long[n + 1];
    factorial[0] = 1;
    for (int i = 1; i <= n; i++) factorial[i] = factorial[i - 1] * i;
    long answer = 0;
    for (String signature : signatures) {
      int[] count = new int[10];
      for (char c : signature.toCharArray()) count[c - '0']++;
      long total = factorial[n];
      for (int c : count) total /= factorial[c];
      if (count[0] > 0) {
        long leadingZero = factorial[n - 1] / factorial[count[0] - 1];
        for (int d = 1; d < 10; d++) leadingZero /= factorial[count[d]];
        total -= leadingZero;
      }
      answer += total;
    }
    return answer;
  }
}
